import React, { useState } from 'react';
import { Download, X, FileText, Calendar, CheckSquare, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import jsPDF from 'jspdf';

export default function ExportModal({ isOpen, onClose, beliefs }) {
  const [mode, setMode] = useState('timeRange');
  const [timeRange, setTimeRange] = useState('all');
  const [selectedIds, setSelectedIds] = useState([]);
  const [isExporting, setIsExporting] = useState(false);

  const timeRanges = [
    { value: 'all', label: 'All time' },
    { value: '7days', label: 'Last 7 days' },
    { value: '30days', label: 'Last 30 days' },
    { value: '90days', label: 'Last 3 months' },
  ];

  const getFilteredBeliefs = () => {
    if (mode === 'selected') {
      return beliefs.filter(b => selectedIds.includes(b.id));
    }
    if (timeRange === 'all') return beliefs;
    const now = new Date();
    let startDate;
    if (timeRange === '7days') startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    else if (timeRange === '30days') startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    else if (timeRange === '90days') startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
    return beliefs.filter(b => new Date(b.created_date) >= startDate);
  };

  const toggleBelief = (id) => {
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const selectAll = () => setSelectedIds(beliefs.map(b => b.id));
  const selectNone = () => setSelectedIds([]);

  const handleExport = () => {
    setIsExporting(true);
    const beliefsToExport = getFilteredBeliefs();

    setTimeout(() => {
      // Create HTML content for archival PDF
      const htmlContent = `
        <!DOCTYPE html>
        <html>
        <head>
          <title>TRACE — Your thoughts, examined</title>
          <style>
            @import url('https://fonts.googleapis.com/css2?family=Libre+Baskerville:wght@400;700&family=Inter:wght@400;500&family=Courier+Prime&display=swap');

            body { 
              font-family: 'Courier Prime', 'Libre Baskerville', monospace;
              color: #2c2c2c;
              background: #fafafa;
              max-width: 600px;
              margin: 0 auto;
              padding: 60px 40px;
              line-height: 1.7;
              font-size: 15px;
            }
            .metadata { 
              font-family: 'Inter', sans-serif;
              font-size: 12px;
              color: #666;
              margin: 8px 0;
              font-weight: 400;
            }
            .section-header { 
              font-family: 'Inter', sans-serif;
              font-size: 13px;
              font-weight: 500;
              text-transform: uppercase;
              letter-spacing: 0.5px;
              margin: 30px 0 15px 0;
              color: #2c2c2c;
            }
            .thought-statement { 
              font-size: 18px;
              font-weight: 700;
              line-height: 1.4;
              margin: 0 0 40px 0;
              color: #2c2c2c;
            }
            .content-section { 
              margin: 25px 0;
              white-space: pre-wrap;
              line-height: 1.8;
            }
            .reflection-entry { 
              margin: 15px 0;
              padding-left: 20px;
              border-left: 2px solid #e0e0e0;
            }
            .reflection-date { 
              font-family: 'Inter', sans-serif;
              font-size: 11px;
              color: #666;
              margin-bottom: 5px;
            }
            .footer { 
              position: fixed;
              bottom: 20px;
              right: 20px;
              font-family: 'Inter', sans-serif;
              font-size: 10px;
              color: #999;
              font-style: italic;
            }
            .page-break { 
              page-break-before: always; 
              margin-top: 80px;
            }
            @media print {
              body { padding: 40px; }
              .footer { position: fixed; }
              .page-break { page-break-before: always; }
            }
          </style>
        </head>
        <body>
          <div style="text-align: center; margin-bottom: 60px;">
            <h1 style="font-family: 'Courier Prime', monospace; font-size: 24px; font-weight: 700; color: #2c2c2c; margin: 0;">
              TRACE — Your thoughts, examined.
            </h1>
          </div>

          <div class="footer">TRACE — Your thoughts, examined.</div>

          ${beliefsToExport.length > 0 ? `
            ${beliefsToExport.map((belief, index) => `
              ${index > 0 ? '<div class="page-break"></div>' : ''}

              <div class="thought-statement">${belief.statement || belief.title || 'Untitled Thought'}</div>

              <div class="metadata">
                Created ${new Date(belief.created_date).toLocaleDateString('en-US', { 
                  year: 'numeric', 
                  month: 'long', 
                  day: 'numeric' 
                })}
                ${belief.confidence ? ` • Confidence ${belief.confidence}/10` : ''}
              </div>

              ${belief.reflections && belief.reflections.length > 0 ? `
                <div class="metadata">
                  Revisited ${new Date(belief.reflections[belief.reflections.length - 1].date).toLocaleDateString('en-US', { 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })}
                </div>
              ` : ''}

              ${belief.reasoning ? `
                <div class="section-header">Why I Believed This</div>
                <div class="content-section">${belief.reasoning}</div>
              ` : ''}

              ${belief.evidence ? `
                <div class="section-header">Evidence / Experience</div>
                <div class="content-section">${belief.evidence}</div>
              ` : ''}

              ${belief.what_would_change ? `
                <div class="section-header">What Would Change My Mind</div>
                <div class="content-section">${belief.what_would_change}</div>
              ` : ''}

              ${belief.reflections && belief.reflections.length > 0 ? `
                <div class="section-header">Reflection Over Time</div>
                ${belief.reflections.map(reflection => `
                  <div class="reflection-entry">
                    <div class="reflection-date">
                      ${new Date(reflection.date).toLocaleDateString('en-US', { 
                        year: 'numeric', 
                        month: 'long', 
                        day: 'numeric' 
                      })}
                      ${reflection.confidence_then ? ` • Confidence ${reflection.confidence_then}/10` : ''}
                      ${reflection.still_believe ? ' • Still believed' : ' • Mind changed'}
                    </div>
                    ${reflection.note ? `<div class="content-section">${reflection.note}</div>` : ''}
                  </div>
                `).join('')}
              ` : ''}
            `).join('')}
          ` : `
            <div style="text-align: center; margin-top: 100px; color: #666;">
              <p>No thoughts to export</p>
            </div>
          `}
        </body>
        </html>
      `;

      // Create a new window and print
      const printWindow = window.open('', '_blank');
      printWindow.document.write(htmlContent);
      printWindow.document.close();

      // Wait for content to load, then print
      printWindow.onload = () => {
        setTimeout(() => {
          printWindow.print();
          printWindow.close();
        }, 500);
      };

      setIsExporting(false);
      onClose();
    }, 100);
  };

  const filteredCount = getFilteredBeliefs().length;

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[9999]">
      <div className="bg-white rounded-lg p-6 w-full max-w-md shadow-xl max-h-[80vh] overflow-hidden flex flex-col">
        <div className="flex justify-between items-center mb-4">
          <div className="flex items-center gap-2">
            <FileText className="w-5 h-5 text-[#5C6B5E]" />
            <h2 className="text-xl font-semibold text-gray-800">Export Thinking Report</h2>
          </div>
          <Button 
            variant="ghost" 
            size="icon" 
            onClick={onClose}
          >
            <X className="h-4 w-4" />
          </Button>
        </div>

        <div className="space-y-6 overflow-y-auto flex-1 pr-2">
          {/* Export mode */}
          <div className="space-y-3">
            <p className="text-sm font-medium text-slate-700">What to export</p>
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => setMode('timeRange')}
                className={`p-3 rounded-xl border-2 text-left transition-all ${
                  mode === 'timeRange' 
                    ? "border-[#5C6B5E] bg-[#E8EDE9]" 
                    : "border-slate-200 hover:border-slate-300"
                }`}
              >
                <Calendar className={`w-4 h-4 mb-1 ${
                  mode === 'timeRange' ? "text-[#5C6B5E]" : "text-slate-400"
                }`} />
                <p className="font-medium text-slate-800 text-sm">By time range</p>
              </button>
              <button
                onClick={() => setMode('selected')}
                className={`p-3 rounded-xl border-2 text-left transition-all ${
                  mode === 'selected' 
                    ? "border-[#5C6B5E] bg-[#E8EDE9]" 
                    : "border-slate-200 hover:border-slate-300"
                }`}
              >
                <CheckSquare className={`w-4 h-4 mb-1 ${
                  mode === 'selected' ? "text-[#5C6B5E]" : "text-slate-400"
                }`} />
                <p className="font-medium text-slate-800 text-sm">Select beliefs</p>
              </button>
            </div>
          </div>

          {/* Time range options */}
          {mode === 'timeRange' && (
            <div className="space-y-3">
              <p className="text-sm font-medium text-slate-700">Time range</p>
              {timeRanges.map(({ value, label }) => (
                <label key={value} className="flex items-center space-x-3 py-2 cursor-pointer">
                  <input
                    type="radio"
                    name="timeRange"
                    value={value}
                    checked={timeRange === value}
                    onChange={() => setTimeRange(value)}
                    className="w-4 h-4"
                  />
                  <span className="text-slate-700">{label}</span>
                </label>
              ))}
            </div>
          )}

          {/* Belief selection */}
          {mode === 'selected' && (
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <p className="text-sm font-medium text-slate-700">Select beliefs</p>
                <div className="flex gap-2">
                  <button onClick={selectAll} className="text-xs text-[#5C6B5E] hover:underline">
                    Select all
                  </button>
                  <span className="text-slate-300">|</span>
                  <button onClick={selectNone} className="text-xs text-slate-500 hover:underline">
                    Clear
                  </button>
                </div>
              </div>
              <div className="max-h-40 overflow-y-auto space-y-1 border border-slate-100 rounded-xl p-2">
                {beliefs.map(belief => (
                  <label
                    key={belief.id}
                    className="flex items-start gap-3 p-2 rounded-lg hover:bg-slate-50 cursor-pointer"
                  >
                    <input
                      type="checkbox"
                      checked={selectedIds.includes(belief.id)}
                      onChange={() => toggleBelief(belief.id)}
                      className="mt-0.5 w-4 h-4"
                    />
                    <div className="flex-1 min-w-0">
                      <p className="text-sm text-slate-700 line-clamp-2">{belief.statement}</p>
                      <p className="text-xs text-slate-400 mt-1">
                        {new Date(belief.created_date).toLocaleDateString()}
                      </p>
                    </div>
                  </label>
                ))}
              </div>
            </div>
          )}

          {/* Preview count */}
          <div className="bg-slate-50 rounded-xl p-3">
            <p className="text-sm text-slate-600">
              <span className="font-semibold text-slate-800">{filteredCount}</span> belief{filteredCount !== 1 ? 's' : ''} will be exported
            </p>
          </div>
        </div>

        {/* Actions */}
        <div className="flex gap-3 pt-3 border-t border-slate-100 mt-3">
          <Button
            variant="outline"
            onClick={onClose}
            className="flex-1 h-10 rounded-xl text-sm"
          >
            Cancel
          </Button>
          <Button
            onClick={handleExport}
            disabled={filteredCount === 0 || isExporting}
            className="flex-1 h-10 rounded-xl bg-[#5C6B5E] hover:bg-[#4a574c] text-white text-sm"
          >
            {isExporting ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <>
                <Download className="w-4 h-4 mr-2" />
                Export PDF
              </>
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}
